function CommonPlayerInfo:Awake()
    -- 玩家头像
    if isNotNull(self.CommonPlayerHeadNode) then
        self.LT_PlayerHeadNode = GetLuaBehaviour(self.CommonPlayerHeadNode.gameObject, "Game.Behaviours.CommonPlayerHeadNode").Env
        self.LT_PlayerHeadNode:SetCallBack(Bind(self, self.OnPlayerHeadClicked))
    end
end

