------------ lifeCycle ------------


function CommonPlayerInfo:CleanProperties()
    self.data = nil
    self.LT_PlayerHeadNode = nil
end

function CommonPlayerInfo:Refresh(data)
    self.data = data
    
    local playerId = data.playerId
    local playerName = data.name
    local playerLevel = data.level
    local avatarId = data.avatar
    local avatarFrameId = data.avatarFrame

    CfUtils.FillText(self.PlayerName, self.data.name)
    CfUtils.FillText(self.PlayerLevel, self.data.level)
    self.LT_PlayerHeadNode:FreshAvatarFrame(avatarId, avatarFrameId)
end

--- 点击玩家头像
function CommonPlayerInfo:OnPlayerHeadClicked()
    if isNotNull(self.data)
    and checkNumber(self.data.playerId) > 0 then
        GameUtils.ShowPlayerInfo( checkNumber(self.data.playerId), nil )
    end
end

return CommonPlayerInfo